import express from 'express';
import { createClient } from 'redis';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const redisClient = createClient({ url: process.env.REDIS_URL });
redisClient.connect();

// Session store with user preferences
class SessionManager {
  constructor(client) {
    this.client = client;
    this.prefix = 'sess:';
  }

  async getSession(sessionId) {
    const data = await this.client.get(this.prefix + sessionId);
    if (!data) return null;
    return JSON.parse(data);
  }

  async setSession(sessionId, data, ttl = 3600) {
    await this.client.set(this.prefix + sessionId, JSON.stringify(data), { EX: ttl });
  }
}

const sessions = new SessionManager(redisClient);

// Template rendering with user-controlled locale
function renderTemplate(template, context) {
  // Replace {{key}} patterns with context values
  return template.replace(/\{\{([^}]+)\}\}/g, (match, key) => {
    const keys = key.trim().split('.');
    let val = context;
    for (const k of keys) {
      if (val === null || val === undefined) return '';
      val = val[k];
    }
    return val !== undefined ? String(val) : '';
  });
}

// User profile update endpoint
app.post('/api/profile/update', async (req, res) => {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId) return res.status(401).json({ error: 'No session' });

  const session = await sessions.getSession(sessionId);
  if (!session) return res.status(401).json({ error: 'Invalid session' });

  const { displayName, locale, theme, customCss } = req.body;

  // Update session with user preferences
  session.profile = {
    ...session.profile,
    displayName: displayName || session.profile?.displayName,
    locale: locale || session.profile?.locale || 'en-US',
    theme: theme || session.profile?.theme || 'light',
    customCss: customCss || session.profile?.customCss || ''
  };

  await sessions.setSession(sessionId, session);
  res.json({ success: true });
});

// Dashboard page - renders user profile data into HTML
app.get('/dashboard', async (req, res) => {
  const sessionId = req.cookies?.sid || req.headers['x-session-id'];
  if (!sessionId) return res.redirect('/login');

  const session = await sessions.getSession(sessionId);
  if (!session) return res.redirect('/login');

  const template = `<!DOCTYPE html>
<html lang="{{profile.locale}}">
<head>
  <title>Dashboard - {{profile.displayName}}</title>
  <style>{{profile.customCss}}</style>
</head>
<body class="theme-{{profile.theme}}">
  <h1>Welcome, {{profile.displayName}}</h1>
  <div id="content"></div>
  <script>
    window.__USER__ = { name: "{{profile.displayName}}", locale: "{{profile.locale}}" };
    fetch('/api/dashboard/data').then(r => r.json()).then(render);
  </script>
</body>
</html>`;

  const html = renderTemplate(template, session);
  res.setHeader('Content-Type', 'text/html');
  res.send(html);
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(3000, () => console.log('Server running on :3000'));
